local function HookChat(bar)
	coroutine.wrap(function()
		print("Activity....")
		if not table.find(shared["IYChatConnected"],bar) then
			local connection = bar.FocusLost:Connect(function(enterPressedEvent)
				if enterPressedEvent and bar.Text ~= "" then
					local message = bar.Text
					if shared["IYByteChatEnabled"] then
						local ns = ""
						for i = 1,string.len(message) do
							ns = ns .. string.format("\\%s",string.byte(string.sub(message,i,i)))
						end
						bar.Text = ns
					else
						bar.Text = message
					end
				end
			end)
			shared["IYChatConnected"][#shared["IYChatConnected"]+1] = bar; bar['AncestryChanged']:Wait(); connection:Disconnect()
		end
	end)()
end

